const fs=require('node:fs/promises');const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});try{for(const url of ['http://127.0.0.1:4400/flatten-pdf','https://pdfpilot.net/compress-pdf']){const page=await browser.newPage({acceptDownloads:true});const record={url,errors:[],console:[],requests:[]};page.on('pageerror',e=>record.errors.push({message:e.message,stack:e.stack}));page.on('console',async m=>{if(m.type()==='error'||m.type()==='warning'){record.console.push({type:m.type(),text:m.text(),location:m.location(),args:await Promise.all(m.args().map(a=>a.evaluate(x=>x instanceof Error?{message:x.message,stack:x.stack}:String(x)).catch(()=>'?')))});}});page.on('requestfailed',r=>record.requests.push({url:r.url(),failure:r.failure()}));await page.goto(url,{waitUntil:'load',timeout:60000});if(url.includes('compress-pdf')){await page.getByRole('button',{name:/Switch to (dark|light) mode/}).waitFor();await page.locator('input[type=file]').first().setInputFiles('tests/fixtures/product-qa/alpha.pdf');await page.getByRole('button',{name:'Compress PDF',exact:true}).click();await Promise.race([page.getByText('Compression failed.',{exact:false}).waitFor({timeout:60000}),page.getByText('Your file is ready',{exact:false}).waitFor({timeout:60000})]).catch(e=>{record.waitFailure=e.message});}record.body=await page.locator('body').innerText();console.log(JSON.stringify(record,null,2));await fs.writeFile('docs/product-completion/runtime-'+(url.includes('compress')?'production-compress':'local-flatten')+'.json',JSON.stringify(record,null,2));await page.close();}}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
